import * as T from '../vendor/three.module.js';
import {MissileSystem,distanceToBox} from './flight.js?v=8';
import {nearestRoad} from './road-network.js?v=8';
export function createActionMode(scene,world,traffic,car,effects,sound,onEvent){
 let destroyed=0;const zero=new T.Matrix4().makeScale(0,0,0),dummy=new T.Object3D(),wreck=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#414346',roughness:1}),240);wreck.frustumCulled=false;wreck.castShadow=true;scene.add(wreck);let wreckCursor=0;for(let i=0;i<240;i++)wreck.setMatrixAt(i,zero);
 const airKit=new T.Group();car.root.add(airKit);const metal=new T.MeshStandardMaterial({color:'#657780',metalness:.7,roughness:.3}),glow=new T.MeshBasicMaterial({color:'#77d7ff',transparent:true,opacity:.8});
 for(const side of [-1,1]){const wing=new T.Mesh(new T.BoxGeometry(1.35,.07,1.2),metal);wing.position.set(side*1.33,.45,.2);airKit.add(wing);for(const z of [-1.2,1.2]){const engine=new T.Mesh(new T.CylinderGeometry(.2,.22,.4,12),metal);engine.position.set(side*.78,.12,z);airKit.add(engine);const flame=new T.Mesh(new T.ConeGeometry(.15,.9,10),glow);flame.rotation.z=Math.PI;flame.position.set(side*.78,-.42,z);airKit.add(flame);}}airKit.visible=false;
 const missiles=Array.from({length:6},()=>{const root=new T.Group(),body=new T.Mesh(new T.CylinderGeometry(.055,.055,.7,8),metal),tip=new T.Mesh(new T.ConeGeometry(.065,.23,8),new T.MeshBasicMaterial({color:'#ffe5ae'}));tip.position.y=.46;root.add(body,tip);scene.add(root);root.visible=false;return root;});
 function floor(x,z){const r=nearestRoad(world.roads,x,z);return Math.max(.04,r.y-Math.max(0,r.distance-r.road.widthAt(r.d)/2)/1.5);}
 function destroy(target){if(target.destroyed)return false;target.destroyed=true;target.speed=0;if(target.model)target.model.root.visible=false;for(const {mesh,index}of target.instances||[]){mesh.setMatrixAt(index,zero);mesh.instanceMatrix.needsUpdate=true;}for(const object of target.objects||[])object.visible=false;destroyed++;for(let i=0;i<5;i++){dummy.position.set(target.x+(Math.random()-.5)*(target.hx??.88)*1.5,(target.y||0)+.22,target.z+(Math.random()-.5)*(target.hz??2.2)*1.5);dummy.rotation.set(Math.random()*.3,Math.random()*Math.PI,.2);dummy.scale.set(.4+Math.random()*1.5,.3+Math.random()*.6,.5+Math.random()*1.3);dummy.updateMatrix();wreck.setMatrixAt(wreckCursor++%240,dummy.matrix);}wreck.instanceMatrix.needsUpdate=true;return true;}
 const system=new MissileSystem((hit,target)=>{effects.explode(hit);sound.explosion();let count=0;for(const object of [...world.colliders,...traffic.cars])if(!object.destroyed&&(object===target||distanceToBox(hit,object)<7)&&destroy(object))count++;onEvent({type:'explosion',hit,count,message:count?`${count}件を破壊`:'着弾'});});
 const direction=new T.Vector3(),up=new T.Vector3(0,1,0);let trailTimer=0;
 return {system,get destroyed(){return destroyed;},floor,canLand(state){const r=nearestRoad(world.roads,state.x,state.z);return r.onSurface&&(!r.road.highway||!r.road.hasBarrier(r.d)||(Math.abs(r.side)>1.5&&Math.abs(r.side)<r.road.widthAt(r.d)/2-1.2))&&!world.colliders.some(b=>!b.destroyed&&Math.abs(b.x-state.x)<b.hx+1.2&&Math.abs(b.z-state.z)<b.hz+2.4)&&!traffic.cars.some(c=>!c.destroyed&&Math.hypot(c.x-state.x,c.z-state.z)<5);},
 fire(state,camera){camera.getWorldDirection(direction);const origin={x:state.x-Math.sin(state.yaw)*2.8,y:state.y+1.15,z:state.z-Math.cos(state.yaw)*2.8};const shot=system.fire(origin,direction);if(shot)sound.launch();return !!shot;},
 update(dt,state){system.step(dt,[...world.colliders,...traffic.cars.filter(c=>!c.destroyed)],floor);trailTimer+=dt;for(let i=0;i<missiles.length;i++){const m=system.items[i],mesh=missiles[i];mesh.visible=!!m;if(m){mesh.position.set(m.x,m.y,m.z);direction.set(m.vx,m.vy,m.vz).normalize();mesh.quaternion.setFromUnitVectors(up,direction);if(trailTimer>.035)effects.trail(m);}}if(trailTimer>.035)trailTimer=0;airKit.visible=!!state.flight;glow.opacity=.7+Math.sin(performance.now()*.02)*.2;effects.update(dt);}
 };
}
